files.content:
.chart-plot{
  position:relative;
}
.chart-plot > svg{
  display:block;
  width:100%;
  height:auto;
}
.chart-label{
  position:absolute;
  font-family:var(--font-mono);
  font-size:var(--t-caption);
  letter-spacing:var(--tr-mono);
  line-height:1;
  white-space:nowrap;
  translate:0 -50%;
  pointer-events:none;
}
.chart-label-axis{
  color:var(--obsidian-200);
}
.chart-label-value{
  color:var(--obsidian-100);
}
.chart-label-center{
  translate:-50% -50%;
}
.chart-label-end{
  translate:-100% -50%;
}
.chart-bars{
  display:grid;
  grid-template-columns:max-content minmax(0,1fr) max-content;
}
.chart-bars-axis{
  display:grid;
  grid-auto-rows:minmax(0,1fr);
  margin-inline-end:var(--s-3);
}
.chart-bars > .chart-bars-reserve, .chart-bars-axis > .chart-label{
  position:static;
  translate:none;
  align-self:center;
}
.chart-bars > .chart-bars-reserve{
  visibility:hidden;
}
.chart-card:has(> .chart-bars){
  container-type:inline-size;
}
@container (min-width: 480px){
  .chart-bars .chart-label{
    font-size:var(--t-small);
  }
}
.chart-plot-sm{
  display:none;
}
@media (max-width: 720px){
  .chart-plot-lg{
    display:none;
  }
  .chart-plot-sm{
    display:block;
  }
}
.chart-card{
  background:var(--obsidian-800);
  color:var(--obsidian-100);
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-lg);
  padding:var(--s-6);
}
.chart-head{
  display:flex;
  align-items:baseline;
  justify-content:space-between;
  gap:var(--s-4);
  margin-bottom:var(--s-5);
}
.chart-head > :first-child{
  min-width:0;
}
.chart-head .t{
  font-size:var(--t-body);
  font-weight:600;
}
.chart-head .s{
  font-family:var(--font-mono);
  font-size:var(--t-caption);
  letter-spacing:var(--tr-mono);
  color:var(--obsidian-300);
  text-transform:uppercase;
}
.chart-big{
  font-size:var(--t-h2);
  font-weight:700;
  line-height:var(--lh-tight);
  letter-spacing:var(--tr-tight);
  font-variant-numeric:tabular-nums;
  margin:var(--s-2) 0;
}
.chart-delta{
  font-family:var(--font-mono);
  font-size:var(--t-caption);
  letter-spacing:var(--tr-mono);
  color:var(--success);
}
.chart-legend{
  list-style:none;
  margin:var(--s-3) 0 0;
  padding:0;
  display:flex;
  flex-wrap:wrap;
  gap:var(--s-4);
  font-size:var(--t-small);
  color:var(--obsidian-200);
}
.chart-legend li{
  display:inline-flex;
  align-items:center;
  gap:var(--s-2);
  white-space:nowrap;
}
